-- ============================================================
-- 0044 — Curadoria dos textos-base da RNC: Comissionamento (CM)
-- Gerado da curadoria multi-agente (draft + verificação normativa).
-- Um UPDATE por item: gravidade + fundamentação + risco + ação específicos.
-- Escrita restrita a super_admin (tabela de plataforma).
-- ============================================================

-- CM-01 (7 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a indefinição de limites de bateria permitir energizar ou testar equipamentos fora da fronteira liberada, atingindo sistemas adjacentes em operação.',
  texto_fundamentacao_normativa = 'A definição documentada das fronteiras do sistema (limites de bateria) delimita o escopo físico e funcional a ser comissionado, estabelecendo quais equipamentos, tubulações, cabos e interfaces integram a etapa e quais permanecem sob responsabilidade de terceiros ou de outras fases. Trata-se de requisito basilar do plano de comissionamento e da matriz de responsabilidades da obra, ancorado no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, e nos fluxogramas de processo/P&ID correspondentes. O critério "Fronteiras do sistema documentadas" constitui pré-condição verificável para o walkdown e para a conclusão mecânica, pois sem limites claros não há como assegurar a completude do sistema nem a rastreabilidade das liberações.',
  texto_risco_consequencia = 'Sistema sem limites de bateria formalmente definidos permite lacunas de escopo e sobreposição de responsabilidades, com equipamentos ou interfaces deixados sem verificação e risco de intervenção ou energização indevida em subsistemas fora da fronteira, atingindo instalações adjacentes eventualmente em operação. A permanência da condição mantém o escopo do comissionamento indeterminado e compromete a validade das liberações subsequentes. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) demarcar e documentar as fronteiras do sistema sobre os P&ID e fluxogramas do projeto executivo aprovado, listando equipamentos, linhas, cabos e interfaces incluídos e excluídos; (ii) validar a delimitação com a matriz de responsabilidades e obter concordância formal das partes (fiscalização, montadora e comissionamento); (iii) evidenciar a definição com registro fotográfico da demarcação em campo e nos documentos ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-01' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter como Crítica sempre que subsistir pendência classe A em aberto; rebaixar a Maior somente após comprovado o encerramento integral dos itens impeditivos.',
  texto_fundamentacao_normativa = 'A punch list classificada em A/B/C hierarquiza as pendências pelo impacto na segurança e na funcionalidade do sistema, sendo os itens classe A (impeditivos) aqueles que devem estar integralmente sanados antes da realização de qualquer teste. Esse escalonamento decorre do procedimento de comissionamento e do plano de inspeção da obra, articulados ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Itens impeditivos (A) zerados antes do teste" é requisito de aceitação da etapa: a existência de pendência A caracteriza condição não segura ou não conforme que veda o avanço para a fase de testes.',
  texto_risco_consequencia = 'Avançar para testes com pendências classe A em aberto expõe o pessoal e os equipamentos a condições impeditivas não resolvidas — falhas de proteção, montagem incompleta ou defeitos funcionais — podendo resultar em acidente, dano ao ativo e invalidação dos resultados de teste, com retrabalho e retorno de etapa. A permanência da condição mantém ativo o risco impeditivo até o efetivo saneamento. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) revisar a punch list e confirmar a classificação A/B/C de cada pendência conforme o procedimento de comissionamento; (ii) sanar integralmente todos os itens classe A e reinspecionar cada um antes de qualquer liberação para teste; (iii) evidenciar o encerramento com registro fotográfico e atualização documental da lista ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-01' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o sistema não limpo puder introduzir detritos em bombas, trocadores, válvulas ou instrumentos, causando dano a equipamento na partida.',
  texto_fundamentacao_normativa = 'A limpeza e o flushing têm por finalidade remover detritos de montagem, carepa, resíduos de solda e contaminantes das linhas e equipamentos, garantindo que fluidos de processo circulem sem transportar partículas capazes de danificar componentes internos. A conformidade é aferida contra o procedimento específico de flushing da obra (critérios de vazão, tempo, filtragem e limpeza dos filtros/telas), articulado ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, e às especificações dos fabricantes dos equipamentos. O critério "Sistemas limpos conforme procedimento" é requisito verificável de aceitação prévia à partida.',
  texto_risco_consequencia = 'Sistema colocado em operação sem limpeza e flushing concluídos permite que detritos remanescentes circulem e danifiquem selos, rolamentos, sedes de válvulas, trocadores e instrumentos, provocando falha precoce, entupimento e parada não programada logo na partida, com custo de reparo e atraso. A permanência da condição mantém o risco de contaminação interna até a efetiva limpeza. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reexecutar o flushing/limpeza do trecho conforme o procedimento aprovado, atendendo aos parâmetros de vazão, tempo e filtragem definidos; (ii) inspecionar e limpar filtros, telas temporárias e pontos baixos, confirmando a ausência de detritos; (iii) evidenciar a conclusão com registro fotográfico das telas/filtros e do relatório de flushing ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-01' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a ausência ou troca de TAG puder induzir intervenção ou manobra em equipamento errado, especialmente em cabos e painéis energizáveis.',
  texto_fundamentacao_normativa = 'A identificação por TAGs de equipamentos, painéis e cabos assegura a correspondência inequívoca entre o item instalado em campo e o documento de projeto (listas, diagramas e P&ID), viabilizando operação, manutenção e rastreabilidade seguras. O requisito decorre do padrão de identificação e do plano de comissionamento da obra, ancorados no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Equipamentos, painéis e cabos identificados" é condição verificável do walkdown, pois a plaquetação completa e legível é pré-requisito para liberação e para a execução segura de manobras e testes.',
  texto_risco_consequencia = 'Identificação incompleta, ilegível ou trocada favorece a intervenção, o comando ou a manobra em equipamento ou circuito errado, com risco de acidente elétrico ou de processo, além de dificultar a manutenção e a rastreabilidade ao longo da vida útil da instalação. A permanência da condição mantém a ambiguidade de identificação até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) confrontar as TAGs de campo com as listas de equipamentos, diagramas e P&ID do projeto, identificando faltas e divergências; (ii) instalar, corrigir ou substituir as identificações faltantes ou ilegíveis com plaquetas padronizadas e duráveis em equipamentos, painéis e cabos; (iii) evidenciar a regularização com registro fotográfico das TAGs instaladas ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-01' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a permanência de travas de transporte ou proteções puder causar dano mecânico na partida ou impedir a atuação de dispositivos de segurança.',
  texto_fundamentacao_normativa = 'A remoção das preservações — travas de transporte, calços, blindagens e proteções temporárias — é condição para que máquinas e equipamentos operem livremente na partida, e o seu registro documenta que nenhum dispositivo provisório permaneceu indevidamente instalado. O requisito decorre das instruções dos fabricantes e do procedimento de conservação/comissionamento da obra, articulados ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Travas de transporte e proteções retiradas e registradas" é requisito verificável de aceitação, pois preservação remanescente caracteriza condição impeditiva à operação segura.',
  texto_risco_consequencia = 'Partida de equipamento com travas de transporte ou proteções ainda instaladas pode provocar dano mecânico grave (empenamento de eixos, ruptura de acoplamentos, sobreaquecimento), impedir a atuação de dispositivos de segurança e gerar parada imediata com avaria do ativo. A permanência da condição mantém o risco de dano na partida até a retirada e o registro das preservações. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) inspecionar cada equipamento conforme a lista de preservações e as instruções do fabricante, localizando travas, calços e proteções temporárias; (ii) retirar todas as preservações remanescentes e restabelecer a condição operacional dos equipamentos; (iii) registrar a remoção em relatório e evidenciar com registro fotográfico dos pontos liberados ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-01' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a documentação ausente respaldar juntas críticas, isolamento elétrico ou alinhamento de máquinas rotativas cuja falha comprometa a integridade do sistema.',
  texto_fundamentacao_normativa = 'Os relatórios de torque, de resistência de isolamento (megger) e de alinhamento constituem a evidência objetiva de que as ligações parafusadas, o isolamento elétrico e o acoplamento das máquinas foram executados e verificados dentro dos valores especificados, tornando rastreável a qualidade da montagem. A exigência decorre das especificações técnicas e dos procedimentos de montagem e comissionamento da obra, articulados ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, e aos dados dos fabricantes. O critério "Relatórios de torque, megger e alinhamento anexados" é requisito verificável de aceitação: sem os registros anexados, a conformidade da montagem não pode ser comprovada nem a liberação sustentada.',
  texto_risco_consequencia = 'Documentação de montagem incompleta impede comprovar que torques, isolamento e alinhamento atendem aos valores especificados, mascarando ligações frouxas, isolamento deficiente ou desalinhamento que podem evoluir para vazamento, falha elétrica, vibração excessiva e avaria de máquinas rotativas em operação. A permanência da condição mantém a montagem sem rastreabilidade de aceitação até a apresentação dos relatórios. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) levantar e anexar ao dossiê os relatórios de torque, de megger e de alinhamento faltantes, com valores medidos, instrumentos e datas; (ii) reexecutar as medições cujos registros não existam ou estejam inconsistentes, corrigindo eventuais desvios identificados; (iii) evidenciar a regularização com registro fotográfico dos ensaios/aferições e do dossiê completo ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-01' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter como Crítica enquanto faltar qualquer das assinaturas exigidas; a liberação formal é requisito indispensável e não comporta rebaixamento sem as três anuências.',
  texto_fundamentacao_normativa = 'A liberação formal, assinada por fiscalização, montadora e comissionamento, materializa a transferência de custódia do sistema e a concordância das três partes de que a etapa de conclusão mecânica foi cumprida e que o sistema está apto ao comissionamento. O requisito decorre do procedimento de comissionamento e da matriz de responsabilidades da obra, ancorados no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Fiscal + montadora + comissionamento" é requisito verificável de aceitação: a ausência de qualquer assinatura descaracteriza a liberação e impede o avanço legítimo do sistema para as fases seguintes.',
  texto_risco_consequencia = 'Avançar sem a liberação formal integralmente assinada retira a base contratual e técnica de transferência de custódia, deixando indefinida a responsabilidade sobre o sistema e permitindo que se prossiga sem a confirmação de que todas as pendências e verificações foram encerradas, com risco de operar sistema não plenamente concluído. A permanência da condição mantém o sistema sem liberação válida até a coleta das três assinaturas. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) consolidar o dossiê de conclusão mecânica e confirmar o encerramento das pendências que condicionam a liberação; (ii) promover o walkdown conjunto e coletar as assinaturas de fiscalização, montadora e comissionamento no termo de liberação; (iii) evidenciar a formalização com registro fotográfico/cópia do termo assinado ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-01' and item_numero = 7;

-- CM-02 (8 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando qualquer ensaio já tiver sido executado ou o equipamento energizado sem procedimento e critérios de aceitação previamente aprovados; rebaixar a Observação se o procedimento estiver em aprovação e nenhum ensaio houver sido iniciado.',
  texto_fundamentacao_normativa = 'O comissionamento a frio pressupõe procedimentos de ensaio formalmente aprovados, com métodos, faixas de instrumentação e critérios de aceitação definidos ANTES da execução, de modo que cada resultado possa ser confrontado com um limite objetivo e rastreável. A fundamentação decorre do plano de comissionamento e das instruções dos fabricantes dos equipamentos, integrados ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Critérios de aceitação definidos antes do teste" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa, evitando que a conformidade seja julgada de forma subjetiva após o ensaio.',
  texto_risco_consequencia = 'A execução de ensaios sem procedimento e critério de aceitação previamente aprovados torna os resultados não conclusivos e a aceitação subjetiva, abrindo caminho para energizar equipamentos cuja conformidade não foi objetivamente demonstrada, com risco de dano ao patrimônio, retrabalho de comissionamento e passivo de responsabilidade técnica. A permanência da condição mantém a etapa de testes sem lastro documental de aceitação. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) elaborar e submeter à aprovação o procedimento de ensaio contendo método, instrumentação exigida, sequência e critérios de aceitação, referenciando normas aplicáveis, dados de fabricante e o projeto executivo aprovado; (ii) vincular formalmente cada relatório de ensaio ao procedimento aprovado, refazendo os testes já realizados fora deste lastro; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) do procedimento aprovado e da matriz de rastreabilidade ensaio × critério, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-02' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o instrumento sem certificado válido tiver sido usado em ensaio já emitido como aprovado; rebaixar a Menor se houver apenas atraso na anexação do certificado, com calibração vigente comprovável.',
  texto_fundamentacao_normativa = 'A validade metrológica dos resultados depende de instrumentos calibrados por laboratório acreditado, com certificados vigentes e rastreabilidade ao padrão nacional (RBC/Rede Brasileira de Calibração, sob acreditação segundo a ISO/IEC 17025). Sem calibração válida e anexada, a medição carece de rastreabilidade e não pode sustentar a aceitação. Aplica-se, ainda, o plano de comissionamento e a especificação técnica do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Certificados RBC válidos anexados aos relatórios" integra o plano de inspeção e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Ensaios executados com instrumentos sem calibração vigente ou sem certificado rastreável comprometem a confiabilidade das medições, podendo mascarar não conformidades reais (isolamento, relação, contato) e conduzir à energização indevida ou à reprovação injusta de equipamentos conformes, com custo de retrabalho e insegurança operacional. A permanência da condição invalida metrologicamente os relatórios afetados. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) levantar todos os instrumentos empregados e confirmar calibração vigente por laboratório acreditado, com incerteza compatível com a grandeza medida; (ii) anexar os respectivos certificados a cada relatório e repetir os ensaios cujos instrumentos estivessem com calibração vencida ou não rastreável; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) das etiquetas/certificados de calibração e da vinculação aos relatórios, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-02' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o valor medido ficar abaixo do critério de norma/fabricante em equipamento destinado à energização; rebaixar a Observação quando o valor atender ao critério, mas o registro por equipamento estiver incompleto.',
  texto_fundamentacao_normativa = 'A medição de resistência de isolamento com megôhmetro verifica a integridade dielétrica dos condutores e equipamentos antes da energização, devendo cada resultado igualar ou superar o critério da norma aplicável e/ou do fabricante. Para instalações de baixa tensão aplica-se a ABNT NBR 5410 e, para média tensão, a ABNT NBR 14039, complementadas pelos limites do fabricante e pelo projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Valores ≥ critério (norma/fabricante) por equipamento" integra o plano de inspeção e constitui requisito verificável de aceitação, exigindo registro individualizado por equipamento e correção da temperatura quando pertinente.',
  texto_risco_consequencia = 'Resistência de isolamento abaixo do critério indica isolação degradada, umidade ou contaminação, elevando o risco de fuga de corrente, curto-circuito, choque elétrico e falha na energização, com dano a pessoas e equipamentos. A ausência de registro por equipamento impede rastrear qual ativo está fora do critério, mantendo latente a possibilidade de energizar isolação comprometida. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) repetir a medição de resistência de isolamento nos equipamentos reprovados ou sem registro, com tensão de ensaio e tempo adequados e correção de temperatura; (ii) para valores abaixo do critério, investigar causa (umidade, contaminação, dano), executar secagem/limpeza ou substituição e remedir até atendimento; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e planilha de resultados por equipamento confrontada ao critério, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-02' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a relação medida divergir do valor de placa além da tolerância em qualquer derivação, ou quando derivações forem omitidas do ensaio; rebaixar a Menor se a divergência decorrer de erro de anotação sanável por reteste imediato.',
  texto_fundamentacao_normativa = 'O ensaio de relação de transformação (TTR) confirma que a relação de espiras do transformador, em TODAS as derivações do comutador, corresponde aos valores de placa dentro da tolerância, atestando integridade dos enrolamentos e correta posição do tape. Aplica-se a ABNT NBR 5356 (transformadores de potência) e os dados de placa/ensaio de fábrica, integrados ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Relação em todas as derivações × placa" integra o plano de inspeção e constitui requisito verificável de aceitação, exigindo a varredura completa das derivações e não apenas do tape nominal.',
  texto_risco_consequencia = 'Divergência da relação de transformação ou ensaio parcial das derivações pode indicar espiras em curto, erro de comutador ou defeito de enrolamento, resultando em tensão de saída incorreta, sobreaquecimento e falha do transformador na energização, com dano ao ativo de maior valor do sistema e interrupção prolongada. A omissão de derivações mantém oculto um possível defeito localizado em tapes não ensaiados. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reexecutar o TTR em todas as derivações do comutador, confrontando cada relação medida com o valor de placa e a tolerância aplicável; (ii) diante de divergência, inspecionar comutador e conexões, corrigir a causa e, persistindo o desvio, acionar o fabricante antes de liberar a energização; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e relatório de TTR completo por derivação, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-02' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a resistência de contato exceder o critério em disjuntor/seccionadora de circuito de potência a energizar; rebaixar a Observação quando dentro do critério, mas faltar registro do trecho/polo medido.',
  texto_fundamentacao_normativa = 'A medição de resistência de contato (micro-ohmímetro, método de queda de tensão em corrente contínua) verifica a qualidade das junções e contatos de disjuntores e seccionadoras, cujo valor deve permanecer dentro do critério estabelecido pelo fabricante do equipamento. Fundamenta-se nas instruções técnicas e valores de referência do fabricante, no plano de comissionamento e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Disjuntores e seccionadoras dentro do critério" integra o plano de inspeção e constitui requisito verificável de aceitação, com medição por polo e comparação ao limite especificado.',
  texto_risco_consequencia = 'Resistência de contato acima do critério gera aquecimento localizado, perda de capacidade de condução e degradação progressiva do contato, podendo evoluir para falha do equipamento de manobra, arco e interrupção não programada sob carga. A ausência de registro por polo impede identificar o contato deficiente, mantendo o ponto quente latente após a energização. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) repetir a medição de resistência de contato por polo com corrente de ensaio adequada, confrontando com o valor de referência do fabricante; (ii) para valores acima do critério, executar limpeza, reaperto com torque especificado ou substituição do contato/pastilha e remedir até atendimento; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e planilha de valores por polo × critério do fabricante, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-02' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o desequilíbrio de resistência entre fases exceder a tolerância indicando defeito de enrolamento/conexão; rebaixar a Menor quando dentro da tolerância, mas sem correção de temperatura ou registro comparativo completo.',
  texto_fundamentacao_normativa = 'A medição de resistência ôhmica dos enrolamentos verifica a continuidade e a uniformidade entre fases, cujo desvio deve permanecer dentro da tolerância de projeto/fabricante após correção para a mesma temperatura de referência. Fundamenta-se nos dados e tolerâncias do fabricante e, para transformadores, na ABNT NBR 5356 (transformadores de potência), integrados ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Comparação entre fases dentro da tolerância" integra o plano de inspeção e constitui requisito verificável de aceitação, exigindo medição das três fases sob mesma base de temperatura.',
  texto_risco_consequencia = 'Diferença de resistência entre fases além da tolerância aponta conexão deficiente, espiras em curto ou terminal frouxo, podendo causar desequilíbrio de corrente, sobreaquecimento e falha do enrolamento na energização, com perda do equipamento e parada não programada. A comparação sem correção de temperatura pode mascarar ou simular um desequilíbrio inexistente, distorcendo a aceitação. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) remedir a resistência dos enrolamentos das três fases, registrando temperatura e aplicando a correção à base de referência antes de comparar; (ii) diante de desvio além da tolerância, inspecionar conexões e terminais, reapertar/refazer contatos e, persistindo, investigar o enrolamento com o fabricante antes de liberar; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e relatório comparativo entre fases corrigido por temperatura, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-02' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — quando a rigidez dielétrica do óleo/meio isolante ficar abaixo do valor mínimo em equipamento a energizar; rebaixar a Maior quando o ensaio for aplicável e estiver pendente sem que o equipamento tenha sido energizado; Observação quando comprovadamente não aplicável ao equipamento.',
  texto_fundamentacao_normativa = 'O ensaio de rigidez dielétrica avalia a capacidade do óleo isolante (ou meio isolante do equipamento) de suportar solicitação de tensão sem ruptura, condição essencial nos equipamentos em que se aplica. Fundamenta-se no método padronizado de determinação da tensão de ruptura de líquidos isolantes (ABNT NBR IEC 60156) e nos valores mínimos definidos pelo fabricante e pela especificação, integrados ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Óleo isolante/equipamentos conforme norma" integra o plano de inspeção e constitui requisito verificável de aceitação, quando o equipamento admitir o ensaio.',
  texto_risco_consequencia = 'Óleo ou meio isolante com rigidez dielétrica abaixo do mínimo indica presença de umidade, partículas ou contaminação, reduzindo a suportabilidade de tensão e elevando o risco de descarga interna, curto-circuito e falha catastrófica do equipamento na energização, com incêndio e dano ao patrimônio. A não realização do ensaio, onde aplicável, mantém indeterminada a condição do isolamento. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) confirmar a aplicabilidade do ensaio ao equipamento e coletar/ensaiar o óleo isolante pelo método padronizado, comparando ao valor mínimo especificado; (ii) para resultados abaixo do critério, executar tratamento (filtragem/termovácuo) ou substituição do fluido e reensaiar até atendimento antes de liberar a energização; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e laudo do ensaio de rigidez dielétrica, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-02' and item_numero = 7;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a ausência de assinatura de executante e fiscalização inviabilizar a rastreabilidade e a aceitação formal dos ensaios; rebaixar a Observação quando faltar apenas assinatura de campo com registro digital equivalente já emitido no sistema.',
  texto_fundamentacao_normativa = 'A validade documental do comissionamento exige que cada relatório de ensaio seja assinado pelo executante e pela fiscalização no sistema, formalizando a responsabilidade técnica e a aceitação do resultado. Fundamenta-se no plano de comissionamento, nos requisitos de gestão da qualidade e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Assinaturas de executante e fiscalização" integra o plano de inspeção e constitui requisito verificável de aceitação, garantindo autoria, rastreabilidade e caráter oficial do registro que libera as etapas subsequentes.',
  texto_risco_consequencia = 'Relatórios sem as assinaturas de executante e fiscalização carecem de valor formal de aceitação, comprometendo a rastreabilidade, a atribuição de responsabilidade e a auditabilidade do comissionamento, e podem levar à liberação de etapas com base em documentos não validados. A permanência da condição mantém pendente a formalização da aceitação dos ensaios já executados. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) identificar os relatórios pendentes de assinatura e coletar, no sistema, as assinaturas do executante responsável e da fiscalização; (ii) instituir bloqueio de fechamento de relatório sem as assinaturas exigidas, evitando reincidência; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) das telas/relatórios assinados no sistema, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-02' and item_numero = 8;

-- CM-03 (7 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a divergência de ajuste inibir função de proteção ou romper a coordenação, deixando trecho energizado sem retaguarda seletiva.',
  texto_fundamentacao_normativa = 'Os ajustes efetivamente parametrizados nos relés devem reproduzir, valor a valor, os definidos no estudo de seletividade e coordenação aprovado, que estabelece pickups, temporizações e curvas de forma a isolar o defeito no menor trecho possível preservando a continuidade do restante do sistema. O arquivo de parametrização é o documento executável dessa proteção e deve ser confrontado integralmente com o estudo e com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Arquivo de parametrização × estudo conferido" integra o plano de inspeção e constitui requisito verificável de aceitação do comissionamento da proteção.',
  texto_risco_consequencia = 'Ajustes divergentes do estudo comprometem a seletividade: um defeito pode ser eliminado por proteção de retaguarda e não pela mais próxima, desligando cargas sadias, ou pode não ser detectado no tempo adequado, expondo equipamentos e pessoas a solicitações térmicas e dinâmicas de curto-circuito. Enquanto a parametrização não for corrigida, a coordenação projetada permanece descaracterizada em operação real. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) confrontar o arquivo de parametrização vigente em cada relé com o estudo de seletividade e o projeto aprovado, listando cada ajuste divergente (pickup, tempo, curva, grupo ativo); (ii) recarregar a parametrização correta, registrando versão do arquivo, data e checksum, e ativar o grupo de ajustes previsto; (iii) reemitir o relatório de conferência ajuste a ajuste e evidenciar a correção ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-03' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o pickup ou o tempo das funções instantâneas ou diferencial (50/87) ficar fora da tolerância, deixando o equipamento sem proteção efetiva.',
  texto_fundamentacao_normativa = 'O ensaio de injeção secundária comprova que cada função de proteção (50/51 de sobrecorrente, 87 diferencial, 21 de distância, 27 de subtensão e 59 de sobretensão) atua no valor de pickup e no tempo parametrizados, injetando grandezas nos terminais de medição do relé. É o ensaio que valida individualmente a resposta de disparo prevista no ajuste e no estudo, referenciado ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Pickup e tempos das funções (50/51/87/21/27/59) conforme ajuste" integra o plano de inspeção e constitui requisito verificável de aceitação, com registro dos valores medidos e das tolerâncias.',
  texto_risco_consequencia = 'Função com pickup ou tempo fora do ajuste opera cedo demais — provocando desligamentos indevidos e indisponibilidade — ou tarde demais/não opera, permitindo que o curto-circuito evolua sem eliminação, com risco de dano ao equipamento protegido, incêndio e exposição de pessoas. A não realização ou a reprovação do ensaio mantém não comprovada a atuação real da proteção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) repetir a injeção secundária das funções reprovadas ou não ensaiadas, registrando valores medidos de pickup e tempo por função e comparando com o ajuste e a tolerância; (ii) corrigir a causa da divergência (reparametrização, saneamento de fiação de medição ou substituição do relé, conforme o caso) e reensaiar até atendimento; (iii) consolidar o protocolo de ensaio assinado e evidenciar a correção ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-03' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando erro de relação, polaridade ou continuidade de TC afetar a função diferencial (87), podendo causar atuação indevida ou omissão de disparo.',
  texto_fundamentacao_normativa = 'A injeção primária, quando exigida, comprova toda a cadeia de medição de corrente do primário do transformador de corrente até a entrada do relé, verificando fio a fio relação, polaridade, continuidade e ausência de circuitos abertos ou invertidos. Só esse ensaio valida a fiação real de TC que a injeção secundária não alcança, conforme o procedimento de comissionamento e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Circuitos de TC comprovados fio a fio" integra o plano de inspeção e constitui requisito verificável de aceitação da instrumentação de proteção.',
  texto_risco_consequencia = 'Erro de polaridade, relação ou continuidade em circuito de TC falseia as correntes vistas pela proteção: a função diferencial pode disparar sem defeito (desligamento indevido) ou deixar de disparar em falta interna, e circuito secundário aberto em TC sob carga gera sobretensões perigosas nos terminais. Sem a comprovação fio a fio, a integridade da medição de proteção permanece não assegurada. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) executar/repetir a injeção primária no circuito exigido, medindo a corrente secundária resultante e conferindo relação e polaridade em cada núcleo e ramal; (ii) sanar as inversões, relações incorretas ou descontinuidades identificadas, refazendo conexões e reapertando bornes, e reensaiar; (iii) registrar o protocolo com valores injetados e lidos e evidenciar a correção ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-03' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a mensagem GOOSE de trip ou de intertravamento não trafegar ou não for supervisionada, resultando em disparo não efetivado.',
  texto_fundamentacao_normativa = 'As mensagens GOOSE substituem a fiação de intertravamento e trip por comunicação horizontal entre IEDs na rede de estação, e devem ser testadas quanto a publicação, assinatura, tempo de transmissão e supervisão de perda de comunicação. Aplica-se a IEC 61850, que define o serviço GOOSE e seus requisitos de desempenho, em conjunto com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, e a matriz de comunicação da subestação. O critério "Intertravamentos e trips via IEC 61850 verificados" integra o plano de inspeção e constitui requisito verificável de aceitação da automação.',
  texto_risco_consequencia = 'GOOSE de trip ou intertravamento não testada pode não ser publicada, não ser assinada pelo IED de destino ou não ter supervisão de falha, de modo que um comando de disparo simplesmente não se efetiva ou uma manobra intertravada não é bloqueada — falhas silenciosas que só se revelam no defeito real. A permanência da condição mantém o esquema de proteção e intertravamento sem comprovação de funcionamento fim a fim. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) testar cada mensagem GOOSE de trip e intertravamento simulando a condição de origem e confirmando a ação no IED de destino, incluindo o teste de supervisão por perda de comunicação; (ii) corrigir mapeamentos, datasets, assinaturas ou parametrização de rede em desacordo e reexecutar o teste; (iii) registrar a matriz de mensagens testadas com resultado e evidenciar a correção ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-03' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando uma lógica ou intertravamento faltante permitir manobra insegura ou omitir um trip previsto na matriz.',
  texto_fundamentacao_normativa = 'As lógicas programáveis e os intertravamentos determinam quais eventos geram trip, bloqueio ou permissão de manobra, e devem ser validados cenário a cenário contra a matriz de trip e os diagramas lógicos de projeto, sem depender apenas da inspeção documental. A validação confronta o comportamento real do sistema com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Matriz de trip testada cenário a cenário" integra o plano de inspeção e constitui requisito verificável de aceitação das lógicas de proteção e controle.',
  texto_risco_consequencia = 'Lógica ou intertravamento incorreto pode liberar manobra sobre equipamento aterrado ou em manutenção, deixar de abrir disjuntores que deveriam abrir em um trip, ou desligar mais do que o necessário. Isso expõe pessoas a risco elétrico direto e o sistema a danos e indisponibilidade. Enquanto a matriz não for integralmente testada, existem cenários de disparo e bloqueio sem comprovação de comportamento. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) percorrer a matriz de trip cenário a cenário, forçando cada condição de entrada e verificando as saídas de trip, bloqueio e permissivo esperadas; (ii) corrigir as lógicas ou intertravamentos que não reproduzirem o projeto e reexecutar os cenários afetados, além dos adjacentes impactados; (iii) registrar a planilha de cenários testados com resultado e evidenciar a correção ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-03' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando divergência de mapeamento fizer um telecomando atuar sobre equipamento diferente do indicado, ou uma sinalização exibir estado falso ao operador.',
  texto_fundamentacao_normativa = 'Os telecomandos e as sinalizações devem ser comprovados ponto a ponto com o supervisório (interface TC-04), verificando que cada comando enviado atua no equipamento correto e que cada estado real (aberto/fechado, alarme, medida) é fielmente refletido na tela. Essa correspondência é definida pela lista de sinais e pelo projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Comando/estado ponto a ponto com o supervisório (interface TC-04)" integra o plano de inspeção e constitui requisito verificável de aceitação da interface de operação.',
  texto_risco_consequencia = 'Ponto trocado, invertido ou não atualizado leva o operador a comandar o equipamento errado ou a decidir com base em estado falso — por exemplo, acreditar que um disjuntor está aberto quando está fechado — o que pode originar manobra sobre circuito energizado e acidente. Sinalização incorreta também mascara alarmes e retarda a resposta a defeitos. Sem a conferência ponto a ponto, a confiabilidade da operação remota fica sem garantia. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) testar ponto a ponto cada telecomando e cada sinalização/medida entre campo e supervisório pela interface TC-04, confirmando destino, sentido e valor; (ii) corrigir mapeamentos, endereços, escalas ou inversões divergentes e reexecutar o ponto afetado; (iii) consolidar a lista de sinais assinada com resultado de cada ponto e evidenciar a correção ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-03' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a ausência de oscilografia impedir a análise de perturbações exigida pela concessionária ou pelo requisito contratual da obra.',
  texto_fundamentacao_normativa = 'A oscilografia registra as formas de onda de tensão e corrente e o estado das funções durante perturbações, sendo essencial para diagnóstico pós-evento, aferição da atuação da proteção e apuração de faltas. Deve estar habilitada, com triggers, canais e tempos de pré e pós-falta configurados e efetivamente testada por registro simulado, conforme os requisitos da concessionária e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, adotando-se formato de arquivo padronizado como boa prática de interoperabilidade. O critério "Registro de perturbação habilitado e testado" integra o plano de inspeção e constitui requisito verificável de aceitação.',
  texto_risco_consequencia = 'Oscilografia não habilitada ou não testada deixa a subestação sem registro de perturbações: após um defeito ou uma atuação da proteção, não há como reconstituir o evento, validar a seletividade ou identificar a causa, dificultando a correção e a prestação de contas à concessionária. A condição não afeta o trip em si, mas suprime a rastreabilidade dos eventos até ser sanada. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) habilitar a função de oscilografia em cada relé, configurando triggers, canais analógicos e digitais e janelas de pré e pós-falta conforme requisito; (ii) testar o registro provocando um trigger e confirmando a gravação, o carregamento e a leitura do arquivo no formato padronizado; (iii) arquivar um registro de exemplo e evidenciar a correção ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-03' and item_numero = 7;

-- CM-04 (7 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter Crítica quando a energização for iniciada ou autorizada sem a Permissão de Trabalho (PT) e a análise de risco assinadas; rebaixar a Maior apenas se a manobra ainda não foi iniciada e houver bloqueio efetivo impedindo a energização até a regularização documental.',
  texto_fundamentacao_normativa = 'A energização é serviço em instalação elétrica e deve ser precedida de Permissão de Trabalho (PT) específica e de análise de risco da manobra, formalmente assinadas pelos responsáveis, conforme a NR-10 (Segurança em Instalações e Serviços em Eletricidade), que exige planejamento, autorização e liberação documentada dos serviços em eletricidade. A PT e a análise de risco assinadas materializam a avaliação prévia dos perigos, a definição das medidas de controle e a responsabilização técnica pela manobra, integrando o procedimento de comissionamento e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Análise de risco da manobra assinada" constitui requisito verificável de aceitação para liberação da energização.',
  texto_risco_consequencia = 'Energizar sem PT específica e análise de risco assinadas suprime a barreira formal de planejamento e autorização, permitindo que a manobra ocorra sem identificação e tratamento dos perigos elétricos, com exposição da equipe a choque e arco elétrico, energização indevida de circuitos e ausência de responsável técnico formalmente designado. A permanência da condição mantém a manobra sem cobertura documental e sem controle de risco até a efetiva regularização. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) suspender qualquer preparação de energização e emitir a PT específica de energização, anexando a análise de risco da manobra devidamente assinada pelos responsáveis técnico e de execução; (ii) revisar as medidas de controle previstas na análise de risco frente às condições reais de campo, confirmando bloqueios, sinalização e delimitação; (iii) evidenciar a documentação assinada e as medidas implantadas com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-04' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se forem encontrados ferramentas, sucata ou corpos estranhos sobre partes energizáveis (barramentos, células, painéis) imediatamente antes da manobra, ou se a área não puder ser integralmente inspecionada e liberada.',
  texto_fundamentacao_normativa = 'O checklist pré-energização é a verificação final que assegura que as áreas a serem energizadas estão limpas, sem ferramentas, materiais ou corpos estranhos capazes de provocar curto-circuito ou arco na primeira aplicação de tensão. Trata-se de medida de controle prévia à energização, coerente com o dever de inspeção e liberação das instalações antes da entrada em serviço previsto na NR-10, e integra o procedimento de comissionamento e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Corpos estranhos e ferramentas removidos das áreas energizáveis" é requisito verificável de aceitação e deve estar concluído e registrado antes da liberação da manobra.',
  texto_risco_consequencia = 'Energizar com checklist pré-energização incompleto e com ferramentas, sucata ou corpos estranhos nas áreas energizáveis pode causar curto-circuito e arco elétrico na aplicação de tensão, com danos a equipamentos, incêndio e risco grave à equipe presente. A permanência da condição mantém as áreas energizáveis sem verificação final de limpeza e desobstrução até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) concluir o checklist pré-energização em todas as áreas energizáveis, inspecionando barramentos, células, painéis e cubículos e removendo ferramentas, materiais e corpos estranhos; (ii) confirmar a desobstrução e a limpeza por dupla verificação (executante e verificador), registrando os itens no formulário de checklist; (iii) evidenciar a conclusão e a condição limpa das áreas com registro fotográfico ({{evidencia_foto_correcao}}) e checklist assinado, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-04' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter Crítica sempre que o controle de instalação/remoção não estiver zerado, pois aterramento temporário esquecido em circuito a energizar provoca curto-circuito franco; rebaixar a Maior apenas se o controle estiver conciliado e faltar somente formalizar o registro documental.',
  texto_fundamentacao_normativa = 'Os aterramentos temporários instalados para garantir a condição de instalação desenergizada devem ser integralmente removidos e contabilizados antes da energização, com controle de instalação/remoção zerado (mesma quantidade instalada e retirada). A gestão e a remoção do aterramento temporário como parte do restabelecimento das condições para reenergização é medida prevista na NR-10 para reenergização de instalações elétricas. O controle numérico zerado integra o procedimento de comissionamento e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, e o critério "Controle de instalação/remoção zerado" é requisito verificável de aceitação para liberação da manobra.',
  texto_risco_consequencia = 'Energizar com aterramento temporário remanescente e controle de instalação/remoção não zerado provoca curto-circuito franco no fechamento, com arco elétrico de alta intensidade, danos severos a equipamentos e disjuntores e risco grave à equipe, além de atuação e possível dano das proteções. A permanência da condição mantém a incerteza sobre a existência de aterramentos esquecidos no circuito até a efetiva conciliação. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) conferir fisicamente o mapa/controle de aterramentos temporários, localizando e removendo todos os conjuntos ainda instalados no trecho a energizar; (ii) conciliar o controle até zerar (quantidade instalada igual à removida), com dupla checagem e assinatura do responsável; (iii) evidenciar a remoção completa e o controle zerado com registro fotográfico ({{evidencia_foto_correcao}}) e planilha de controle assinada, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-04' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se a manobra envolver média/alta tensão ou interligação com sistema em operação sem sequência aprovada, responsáveis nomeados e comunicação definida; rebaixar a Observação apenas se pendência for exclusivamente formal em circuito de baixa tensão isolado.',
  texto_fundamentacao_normativa = 'A sequência de manobra deve ser aprovada e formalizada em passo a passo, com responsáveis nomeados por etapa e protocolo de comunicação definido, de modo a garantir execução ordenada, sem improviso e com comando único durante a energização. A exigência de procedimento de trabalho e de sequência lógica de operações, com definição de responsáveis e comunicação, decorre do dever de planejamento e execução controlada de serviços em eletricidade da NR-10, e integra o procedimento de comissionamento e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Passo a passo com responsáveis e comunicação definidos" é requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Executar a energização sem sequência de manobra aprovada e sem responsáveis e comunicação definidos favorece operações fora de ordem, acionamento indevido de equipamentos, ausência de comando único e falhas de comunicação entre campo e sala de comando, com risco de curto-circuito, arco elétrico e danos a pessoas e ativos. A permanência da condição mantém a manobra sem roteiro validado e sem responsabilização por etapa até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) elaborar/aprovar a sequência de manobra em passo a passo, detalhando cada operação, o equipamento associado e o responsável por etapa; (ii) definir e registrar o protocolo de comunicação (canais, confirmações e comando único), realizando alinhamento prévio com a equipe; (iii) evidenciar a sequência aprovada e assinada e o registro do alinhamento com foto/documento ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-04' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter Crítica quando a instalação depender de interligação com a rede da concessionária ou de despacho do ONS e a energização ocorrer sem autorização e horário confirmados; rebaixar a Maior se a instalação for eletricamente isolada da rede externa, sem interface com terceiros.',
  texto_fundamentacao_normativa = 'Quando a energização tem interface com a rede da concessionária ou com a operação do sistema (ONS), a coordenação prévia, com autorizações e janelas de horário confirmadas, é condição para a manobra, evitando energização não autorizada e conflito operacional. A coordenação com o agente da rede decorre das regras de acesso e conexão e dos procedimentos de rede aplicáveis à interligação, além do dever de planejamento e autorização de serviços da NR-10; integra o procedimento de comissionamento e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Autorizações e horários confirmados" é requisito verificável de aceitação para liberação da manobra.',
  texto_risco_consequencia = 'Energizar sem a coordenação com a concessionária/ONS concluída pode gerar energização não autorizada da interface, conflito com manobras de terceiros, retorno de tensão indevido, sanções contratuais e regulatórias e risco a equipes externas que atuem no trecho comum. A permanência da condição mantém a manobra sem autorização e sem janela confirmada do agente de rede até a efetiva coordenação. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) formalizar a coordenação com a concessionária/ONS, obtendo por escrito a autorização de manobra e a janela de horário confirmada; (ii) alinhar o ponto e as condições de interligação, os contatos de operação e o protocolo de liberação/confirmação entre as partes; (iii) evidenciar as autorizações e o horário confirmados com registro documental e fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-04' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter Crítica quando houver pessoal na área sem EPI adequado ao risco de arco elétrico, área não isolada ou presença de pessoal não essencial durante a manobra; rebaixar a Maior apenas se a exposição estiver controlada e a pendência for de formalização do dimensionamento.',
  texto_fundamentacao_normativa = 'A energização deve ser conduzida com equipe mínima essencial, área isolada e delimitada e EPI/vestimenta adequados ao risco de arco elétrico, protegendo os trabalhadores contra os efeitos térmicos e mecânicos do arco. A NR-10 exige medidas de proteção coletiva e individual e vestimenta compatível com o risco térmico do arco elétrico, além da restrição de acesso à zona controlada apenas a pessoal autorizado e essencial. O requisito integra o procedimento de comissionamento e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}; o critério "Área isolada; somente pessoal essencial" é requisito verificável de aceitação para liberação da manobra.',
  texto_risco_consequencia = 'Realizar a energização com equipe superdimensionada, área não isolada ou EPI inadequado ao arco elétrico expõe trabalhadores a queimaduras graves, lesões por pressão e projeção de partículas em caso de falha na manobra, ampliando o número de pessoas atingidas por não restringir a presença ao essencial. A permanência da condição mantém pessoas expostas ao risco de arco sem a proteção e o isolamento devidos até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reduzir a equipe ao mínimo essencial e afastar pessoal não indispensável, isolando e sinalizando a área da manobra com delimitação de zona controlada; (ii) conferir e disponibilizar EPI/vestimenta adequados ao risco de arco elétrico, verificando conformidade e uso correto antes da energização; (iii) evidenciar o isolamento da área, a lista de pessoal essencial e o uso dos EPI com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-04' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se a termografia inicial ou o acompanhamento revelar ponto quente, aquecimento anormal ou defeito incipiente sem tratamento; rebaixar a Observação apenas se o monitoramento foi realizado e registrado e a pendência for exclusivamente de arquivamento do relatório.',
  texto_fundamentacao_normativa = 'Após a energização, o monitoramento nas primeiras horas e a termografia inicial permitem detectar aquecimentos anormais, conexões mal executadas e defeitos incipientes ainda em regime controlado, antes da entrada plena em operação. Trata-se de boa prática consolidada de comissionamento e de manutenção preditiva, alinhada ao acompanhamento pós-energização como medida de verificação da instalação em serviço; integra o procedimento de comissionamento e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Acompanhamento nas primeiras horas; termografia inicial" é requisito verificável de aceitação para o encerramento da etapa de energização.',
  texto_risco_consequencia = 'A ausência de monitoramento pós-energização e de termografia inicial permite que pontos quentes, conexões deficientes e defeitos incipientes evoluam sem detecção, podendo levar a falha, sobreaquecimento, curto-circuito e incêndio já em operação, além de indisponibilidade não programada. A permanência da condição mantém a instalação recém-energizada sem verificação térmica e sem acompanhamento das primeiras horas até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) executar o acompanhamento das primeiras horas após a energização, registrando grandezas elétricas e ocorrências, e realizar a termografia inicial das conexões e equipamentos sob carga; (ii) tratar de imediato eventuais pontos quentes ou anomalias identificadas, reapertando conexões ou corrigindo defeitos e reinspecionando; (iii) evidenciar o monitoramento e a termografia com relatório e registro fotográfico/termográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-04' and item_numero = 7;

-- CM-05 (6 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se os inversores operarem fora dos limites de tensão, corrente ou temperatura definidos pelo fabricante, com risco de desarme, degradação ou dano ao equipamento e à rede.',
  texto_fundamentacao_normativa = 'Os testes funcionais em carga verificam se inversores e subsistemas partem, sincronizam e operam nos pontos de trabalho previstos, sob condições reais de geração. Constituem etapa de comissionamento a quente conforme a ABNT NBR 16274 (sistemas fotovoltaicos conectados à rede — requisitos de documentação, ensaios de comissionamento, inspeção e avaliação de desempenho) e as instruções do fabricante dos inversores, além do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Inversores/sistemas operando conforme fabricante" integra o plano de inspeção e é requisito de aceitação da energização e da entrada em operação comercial.',
  texto_risco_consequencia = 'Colocar em operação inversores sem comprovação do funcionamento em carga pode mascarar defeitos de partida, sincronismo, proteção anti-ilhamento ou dissipação térmica, resultando em desarmes recorrentes, perda de geração, degradação acelerada e risco de dano ao inversor e à rede da concessionária. A permanência da condição mantém o sistema em operação sem validação funcional documentada. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) executar os testes funcionais em carga de cada inversor/subsistema seguindo o roteiro do fabricante, registrando pontos de trabalho, alarmes e parâmetros de proteção; (ii) tratar as não conformidades detectadas (ajuste de parametrização, correção de instalação ou substituição de componente defeituoso) e repetir o ensaio; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e anexar os relatórios/telas de ensaio à documentação de comissionamento, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-05' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se os desvios das curvas indicarem strings em circuito aberto, módulos com defeito ou perdas por descasamento que comprometam a geração contratada.',
  texto_fundamentacao_normativa = 'O levantamento amostral de curvas I-V confronta o desempenho real de cada string com a curva esperada, revelando descasamento, sujeira, sombreamento, resistências de contato e módulos defeituosos. A medição e a análise seguem a ABNT NBR 16274 (ensaios de comissionamento — categoria de verificação de desempenho) e o critério de amostragem do plano de inspeção, referenciados também às condições de projeto do executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Amostragem conforme plano; desvios investigados" torna a curva I-V um ensaio verificável de aceitação das strings.',
  texto_risco_consequencia = 'Deixar de levantar as curvas I-V na amostragem prevista, ou não investigar os desvios encontrados, permite que perdas por descasamento, conexões deficientes ou módulos degradados passem despercebidos, reduzindo a geração e o Performance Ratio ao longo de toda a vida útil da usina, com prejuízo de receita e dificuldade posterior de rastrear a causa. A permanência da condição mantém as strings sem validação de desempenho. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) executar as medições de curva I-V na quantidade e nos pontos definidos pelo plano de amostragem, registrando irradiância e temperatura no momento do ensaio; (ii) investigar cada string com desvio relevante frente à curva esperada, identificando e sanando a causa raiz (limpeza, reaperto de conexões, correção de polaridade/série ou troca de módulo); (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e anexar as curvas I-V pós-correção, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-05' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — ponto quente em conexão elétrica ou módulo caracteriza risco iminente de incêndio e dano; manter Crítica salvo evidência de que o gradiente térmico está abaixo do critério e sem tendência de agravamento.',
  texto_fundamentacao_normativa = 'A termografia por infravermelho localiza pontos quentes em conexões, fusíveis, conectores, caixas de junção e células/módulos, indicando resistências de contato elevadas, correntes de fuga ou células em mismatch. O ensaio integra o comissionamento a quente previsto na ABNT NBR 16274 e adota como critério de gradiente térmico o limite definido pelo plano de inspeção e pelas boas práticas de inspeção termográfica de instalações elétricas, complementados pelo projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Sem pontos quentes acima do critério" é requisito verificável de segurança e de aceitação da instalação.',
  texto_risco_consequencia = 'Um ponto quente não tratado em conexão ou módulo evolui para carbonização, falha do conector, abertura de circuito e, no limite, princípio de incêndio, além de perda de geração da string afetada e risco à equipe de operação. A permanência da condição mantém ativo um foco de sobreaquecimento sob energia. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reinspecionar por termografia os pontos sinalizados sob condição de carga representativa, confirmando o gradiente térmico frente ao critério adotado; (ii) desenergizar com segurança e sanar a causa (reaperto ao torque especificado, substituição de conector/fusível/módulo ou correção da conexão) e repetir a termografia; (iii) evidenciar a correção com registro fotográfico e imagem termográfica ({{evidencia_foto_correcao}}), anexando o laudo comparativo antes/depois e submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-05' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o PR apurado ficar abaixo da meta contratual e configurar penalidade, gatilho de rejeição de recebimento ou indício de falha sistêmica de geração.',
  texto_fundamentacao_normativa = 'O Performance Ratio (PR) mede a eficiência global da usina descontando o efeito da irradiância e da temperatura, sendo o principal indicador de aceitação de desempenho. O cálculo, o período de apuração e o método de correção devem seguir, sobretudo, as condições, a meta e a fórmula pactuadas em contrato, apoiados na avaliação de desempenho prevista pela ABNT NBR 16274 e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "PR conforme contrato; período e método registrados" torna o indicador rastreável e auditável para o aceite da fiscalização.',
  texto_risco_consequencia = 'Apurar o PR sem registrar período, método e dados de irradiância/temperatura, ou apresentá-lo abaixo da meta contratual, inviabiliza a comprovação de desempenho, pode acionar penalidades e mascara perdas sistêmicas (soiling, mismatch, indisponibilidade, subdimensionamento), comprometendo a receita esperada ao longo da operação. A permanência da condição mantém o aceite de desempenho pendente. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) recalcular o PR com o método e o período definidos em contrato, documentando as séries de geração, irradiância no plano dos módulos e temperatura utilizadas; (ii) quando o PR ficar abaixo da meta, investigar e tratar as causas das perdas (limpeza, correção de strings/inversores, ajuste de monitoramento) e reapurar o indicador; (iii) evidenciar a correção com registro fotográfico e relatório de cálculo ({{evidencia_foto_correcao}}), submetendo o memorial de PR à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-05' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se a disponibilidade apurada ficar abaixo do mínimo contratual do período de teste ou se a medição não puder ser reconstituída por falha de registro.',
  texto_fundamentacao_normativa = 'A disponibilidade quantifica a fração do período de teste em que a usina esteve apta a gerar, sendo indicador contratual de confiabilidade da planta e dos inversores. A metodologia, a janela de medição e o valor mínimo aceitável são definidos pelo contrato/PPA e pelo plano de comissionamento, com apoio das boas práticas de monitoramento via SCADA e referência ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Medição no período de teste conforme contrato" torna a disponibilidade um requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Não registrar a disponibilidade no período de teste, ou apurá-la abaixo do patamar contratual, impede a comprovação de que a usina opera de forma confiável, podendo indicar falhas recorrentes de inversores, comunicação ou subestação, com risco de rejeição do recebimento e de penalidades por indisponibilidade na operação comercial. A permanência da condição mantém a confiabilidade da planta sem comprovação. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) consolidar os registros de disponibilidade no período de teste a partir do SCADA/monitoramento, discriminando paradas, causas e durações; (ii) tratar as causas de indisponibilidade identificadas (falhas de inversor, comunicação, proteção ou rede) e, quando exigido pelo contrato, estender ou repetir o período de medição; (iii) evidenciar a correção com registro fotográfico e relatório de disponibilidade ({{evidencia_foto_correcao}}), submetendo o memorial à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-05' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a ausência do aceite formal bloquear o recebimento provisório/definitivo, a entrada em operação comercial ou marcos contratuais de pagamento.',
  texto_fundamentacao_normativa = 'O relatório de performance consolida os ensaios a quente (testes funcionais, curvas I-V, termografia, PR e disponibilidade) e sua aprovação formal pela fiscalização/cliente é o ato que encerra o comissionamento de desempenho. O requisito decorre do plano de comissionamento e das condições contratuais de recebimento, apoiado na ABNT NBR 16274 quanto à documentação de comissionamento e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Aprovação formal da fiscalização/cliente" é a condição de aceite documental da etapa.',
  texto_risco_consequencia = 'Encerrar o comissionamento sem o aceite formal do relatório de performance deixa a etapa juridicamente incompleta, sem rastreabilidade da aprovação e sem base documental para o recebimento e para eventuais garantias, criando divergências entre as partes e insegurança quanto ao início da operação comercial. A permanência da condição mantém o comissionamento sem fechamento formal. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) compilar o relatório de performance com todos os ensaios, memoriais de cálculo e evidências, sanando pendências apontadas pela fiscalização/cliente; (ii) submetê-lo à análise e obter a aprovação formal registrada (assinatura/termo de aceite), com data e responsáveis identificados; (iii) evidenciar a conclusão com registro fotográfico e cópia do termo de aceite ({{evidencia_foto_correcao}}), arquivando na documentação as-built e submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-05' and item_numero = 6;

-- CM-06 (7 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se remanescer pendência que impeça a operação segura ou o uso pretendido da instalação; rebaixar a Observação se restarem apenas itens estéticos ou de acabamento, já pactuados com responsável e data.',
  texto_fundamentacao_normativa = 'O encerramento do comissionamento exige punch list zerado ou formalmente aceito com prazo, cada pendência residual vinculada a responsável e data de solução, condição que assegura rastreabilidade das entregas incompletas. Fundamenta-se no plano de comissionamento e no contrato da obra, complementados pelas boas práticas de gestão de qualidade, que condicionam a transferência da instalação ao tratamento controlado das pendências. O critério "Pendências residuais com responsável e data" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa, não admitindo pendência aberta sem responsável e prazo definidos.',
  texto_risco_consequencia = 'Punch list em aberto, sem responsável e data, ou aceito sem prazo, transfere para a operação pendências não resolvidas cuja titularidade se dilui após o recebimento, gerando disputa contratual, retrabalho às custas do contratante e risco de a instalação operar com deficiências não sanadas. A permanência da condição mantém indefinida a fronteira entre o executado e o pendente até a efetiva regularização. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) consolidar o punch list atualizado, atribuindo a cada pendência responsável nominal e data-limite de solução; (ii) executar ou formalizar o aceite com prazo das pendências, distinguindo as impeditivas de recebimento das meramente residuais; (iii) evidenciar a baixa de cada item com registro fotográfico ({{evidencia_foto_correcao}}) e atualização da lista assinada pelas partes, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-06' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se a lacuna no data book atingir certificados, ensaios ou relatórios que comprovem segurança, estanqueidade ou desempenho de sistemas críticos; rebaixar a Observação se faltarem apenas cópias de manuais recuperáveis de imediato.',
  texto_fundamentacao_normativa = 'O data book (dossiê de qualidade) deve reunir, de forma organizada e indexada, certificados, ensaios, relatórios e manuais que comprovem a conformidade do que foi executado, constituindo o acervo de rastreabilidade da obra. Fundamenta-se no contrato, na especificação técnica e nas boas práticas de gestão da informação documentada da qualidade, que exigem preservação e recuperabilidade dos registros de comprovação. O critério "Certificados, ensaios, relatórios e manuais organizados" integra o plano de inspeção e é requisito verificável de aceitação, pois sem o acervo completo não há como demonstrar objetivamente a qualidade entregue.',
  texto_risco_consequencia = 'Data book incompleto ou desorganizado priva o contratante da comprovação documental de ensaios, certificados e desempenho, inviabilizando auditorias, garantias e a defesa técnica em eventual sinistro, além de dificultar a operação e manutenção por ausência de manuais. A permanência da condição mantém a obra sem lastro documental de conformidade até a complementação do dossiê. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) levantar, a partir de índice de referência, os documentos ausentes ou desatualizados do data book (certificados, ensaios, relatórios e manuais); (ii) reunir, organizar e indexar o acervo completo, em versão física e/ou digital pesquisável, conferindo a correspondência com os sistemas executados; (iii) evidenciar a entrega com registro fotográfico ({{evidencia_foto_correcao}}) e protocolo de recebimento do data book assinado, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-06' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se as divergências entre o executado e o desenho de projeto envolverem redes enterradas, estruturas ou instalações cuja localização incorreta possa causar acidente em intervenção futura.',
  texto_fundamentacao_normativa = 'O as built deve retratar fielmente a obra conforme executada, com os desenhos revisados incorporando todas as alterações havidas em relação ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, servindo de base para operação, manutenção e futuras intervenções. Fundamenta-se no contrato, na especificação e nas boas práticas de documentação técnica, que exigem a representação do estado final real da obra. O critério "Desenhos revisados conforme executado" integra o plano de inspeção e é requisito verificável de aceitação, pois o as built é o registro oficial da geometria e das interferências efetivamente implantadas.',
  texto_risco_consequencia = 'As built ausente ou divergente do executado induz a operação e a manutenção a decisões sobre uma configuração inexistente, elevando o risco de danos a redes e estruturas em intervenções futuras, com retrabalho, custos de sondagem e potencial acidente ao atingir interferência não cadastrada. A permanência da condição mantém desatualizado o registro oficial da obra até a entrega dos desenhos corrigidos. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) confrontar os desenhos de projeto com o efetivamente executado, mapeando divergências de geometria, traçado e interferências; (ii) revisar e emitir os desenhos as built em revisão controlada, incorporando todas as alterações e cotas reais levantadas em campo; (iii) evidenciar a entrega com registro fotográfico ({{evidencia_foto_correcao}}) e protocolo dos arquivos as built aprovados, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-06' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — a ausência de ART recolhida configura irregularidade legal de responsabilidade técnica; manter como Crítica enquanto houver serviço executado, fiscalizado ou projetado sem a respectiva anotação registrada no conselho.',
  texto_fundamentacao_normativa = 'As Anotações de Responsabilidade Técnica (ART) de execução, fiscalização e projetos devem estar recolhidas e vinculadas aos profissionais e à obra, individualizando a responsabilidade técnica de cada atividade. A exigência decorre da Lei nº 6.496/1977, que instituiu a ART como registro obrigatório perante o conselho profissional (CREA), assegurando a rastreabilidade da responsabilidade técnica; às atividades de arquitetura corresponde o instrumento equivalente (RRT). O critério "Execução, fiscalização e projetos" integra o plano de inspeção e é requisito verificável de aceitação, pois nenhuma etapa técnica pode ser recebida sem a correspondente anotação de responsabilidade.',
  texto_risco_consequencia = 'A falta de ART recolhida deixa serviços de execução, fiscalização ou projeto sem responsável técnico legalmente anotado, expondo a obra a autuação do conselho, à nulidade de garantias e à impossibilidade de imputar responsabilidade em caso de vício ou acidente, além de comprometer a regularidade jurídica da entrega. A permanência da condição mantém a obra em situação de irregularidade de responsabilidade técnica até o recolhimento das anotações. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) relacionar todas as atividades exigíveis (execução, fiscalização e projetos) e confrontar com as ART/RRT já recolhidas, identificando as faltantes; (ii) providenciar o recolhimento e a vinculação das anotações pendentes junto ao conselho, com os dados da obra e dos profissionais responsáveis; (iii) evidenciar a regularização com registro ({{evidencia_foto_correcao}}) e anexação das ART/RRT ao data book, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-06' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se o instrumento sem calibração rastreável tiver sido usado em teste de aceitação de sistema crítico (pressão, estanqueidade, elétrico), invalidando o resultado; rebaixar a Observação se o certificado existir e faltar apenas anexá-lo.',
  texto_fundamentacao_normativa = 'Os instrumentos empregados nos testes devem possuir certificado de calibração vigente e rastreável, anexado ao acervo, de modo a garantir a confiabilidade metrológica das medições que embasam a aceitação. Fundamenta-se no requisito de rastreabilidade metrológica ao Sistema Internacional por cadeia ininterrupta de calibrações, com certificados emitidos por laboratório competente (referência da NBR ISO/IEC 17025) e vínculo à Rede Brasileira de Calibração/INMETRO. O critério "Instrumentos usados nos testes rastreáveis" integra o plano de inspeção e é requisito verificável de aceitação, pois medição sem rastreabilidade não comprova conformidade.',
  texto_risco_consequencia = 'Instrumento sem calibração rastreável torna incertos os resultados dos testes de aceitação, podendo aprovar sistema fora de tolerância ou reprovar sistema conforme, com risco de operação insegura, retrabalho e perda de validade dos ensaios já realizados. A permanência da condição mantém sob suspeita metrológica todos os testes dependentes daquele instrumento até a comprovação de rastreabilidade. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) identificar os instrumentos utilizados nos testes e verificar a vigência e a rastreabilidade dos respectivos certificados de calibração; (ii) obter os certificados válidos ou recalibrar os instrumentos em laboratório competente, repetindo os ensaios cujos resultados dependeram de instrumento não rastreável; (iii) evidenciar a regularização com registro fotográfico ({{evidencia_foto_correcao}}) e anexação dos certificados ao data book, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-06' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se a operação envolver sistemas de risco (elétricos, pressurizados, rotativos ou de segurança) cuja operação por pessoal não treinado possa causar acidente; rebaixar a Observação se faltar apenas formalizar a lista de presença de treinamento já ministrado.',
  texto_fundamentacao_normativa = 'O treinamento de operação e manutenção (O&M) deve ser efetivamente realizado e comprovado por lista de presença e entrega de material didático, habilitando a equipe do contratante a operar e manter a instalação com segurança e dentro dos parâmetros de projeto. Fundamenta-se no contrato, na especificação e nas boas práticas de transferência de conhecimento operacional, condição para a passagem segura da instalação ao usuário. O critério "Lista de presença e material entregue" integra o plano de inspeção e é requisito verificável de aceitação, pois a capacitação da equipe é entrega contratual objetivamente comprovável.',
  texto_risco_consequencia = 'A ausência de treinamento de O&M comprovado entrega a instalação a uma equipe sem qualificação para operá-la e mantê-la, elevando o risco de erro de operação, dano ao equipamento, perda de garantia por uso indevido e acidente por manobra incorreta em sistemas de risco. A permanência da condição mantém a operação sem capacitação formal registrada até a realização e comprovação do treinamento. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) programar e ministrar o treinamento de O&M com escopo aderente aos sistemas entregues, incluindo procedimentos de segurança e de manutenção; (ii) entregar o material didático e os manuais à equipe do contratante, colhendo lista de presença assinada dos participantes; (iii) evidenciar a realização com registro fotográfico ({{evidencia_foto_correcao}}) e anexação da lista de presença e do material ao data book, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-06' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — o termo de aceitação (TAC/TAF) formaliza a transferência de responsabilidade entre as partes; manter como Crítica enquanto ausente, salvo se pendente apenas de assinatura já com todos os requisitos anteriores atendidos, quando cabe Maior.',
  texto_fundamentacao_normativa = 'O termo de aceitação (TAC/TAF) deve estar assinado, formalizando entre as partes a aceitação do comissionamento e da instalação, com marco de transferência de responsabilidade, início de garantias e encerramento contratual da etapa. Fundamenta-se no contrato e nas boas práticas de comissionamento, que condicionam a formalização do aceite ao atendimento prévio de punch list, data book, as built, ART, calibrações e treinamento. O critério "TAC/TAF formalizado entre as partes" integra o plano de inspeção e é requisito verificável de aceitação, pois é o ato que documenta o recebimento e delimita as responsabilidades pós-entrega.',
  texto_risco_consequencia = 'A ausência do termo de aceitação assinado mantém indefinido o marco de transferência de responsabilidade, deixando incerto o início da garantia, a titularidade sobre a operação e o encerramento contratual, com risco de litígio sobre quem responde por falhas surgidas após a ocupação. A permanência da condição mantém a etapa juridicamente inconclusa até a formalização do aceite. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) confirmar o atendimento dos requisitos precedentes (punch list, data book, as built, ART, calibrações e treinamento) que condicionam o aceite; (ii) elaborar e colher a assinatura do TAC/TAF pelas partes, consignando eventuais ressalvas e prazos remanescentes; (iii) evidenciar a formalização com registro ({{evidencia_foto_correcao}}) e arquivamento do termo assinado no data book, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CM-06' and item_numero = 7;

